  "measure_id": "MEAS-BB31064A",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Caps residential rent increases at 5 percent within any 12-month period, but exempts units that were first occupied within the past 15 years."
    }
  ],
  "findings": [
