      "effect": "advances",
      "direction": null,
      "quote": "A landlord of a residential unit may not increase rent by more than 5 percent in any 12-month period.",
      "mechanism": "Strengthens renter protections by legally capping annual rent increases at 5 percent for covered residential units.",
      "certainty": "stated"
    },
